  <line x1="80" y1="60" x2="200" y2="60" stroke="#3498db" stroke-dasharray="3,3" stroke-width="1"/>
  <line x1="80" y1="140" x2="195" y2="64" stroke="#e74c3c" stroke-width="2.5" marker-end="url(#vector-arrow)"/>
