INSERT INTO content (sid, cid, topic, notes, qs) VALUES (
  'math',
  'vectors',
  'Vector Notation',
  '
<h2> Vector Notation</h2>

<h3> DEEP NOTES</h3>
<p>
A vector is a quantity with BOTH magnitude and direction. It can be represented in multiple equivalent forms.
</p>

<pre>
a = (x, y)
a = xi + yj
</pre>

 i = unit vector in horizontal direction  
 j = unit vector in vertical direction  

---

<h3> WORKED EXAMPLES (STEP BY STEP)</h3>

<p><b>Example 1</b></p>
<p><b>Question:</b> Write (3, 4) in i, j form</p>
<p><b>Step 1:</b> x-component = 3 → 3i</p>
<p><b>Step 2:</b> y-component = 4 → 4j</p>
<p><b>Final Answer:</b> 3i + 4j</p>

<br>

<p><b>Example 2</b></p>
<p><b>Question:</b> Convert (−2, 5) to i, j form</p>
<p><b>Step 1:</b> x = −2 → −2i</p>
<p><b>Step 2:</b> y = 5 → 5j</p>
<p><b>Final Answer:</b> −2i + 5j</p>

<br>

<p><b>Example 3</b></p>
<p><b>Question:</b> Convert 7i − 3j into coordinate form</p>
<p><b>Step 1:</b> x-component = 7</p>
<p><b>Step 2:</b> y-component = −3</p>
<p><b>Final Answer:</b> (7, −3)</p>

---

<h3> DIAGRAM</h3>

<pre>
          j ↑
            |
            |     • (x, y)
            |
------------•--------------→ i
          origin
</pre>

---

<h3> REAL WORLD APPLICATION</h3>
<ul>
<li>GPS navigation directions</li>
<li>Airplane movement tracking</li>
<li>Game character motion (2D/3D)</li>
</ul>

---
',
  '[{"q":"Convert (-3, 7) into i and j vector form","hint":"split components","steps":["Step 1: Identify x-component = -3","Step 2: Identify y-component = 7","Step 3: Multiply x by i → -3i","Step 4: Multiply y by j → 7j","Step 5: Combine components"],"ans":"-3i + 7j","why":"Each coordinate is written along its axis direction"},{"q":"Convert (0, 6) into i and j form","hint":"x is zero","steps":["Step 1: Identify x-component = 0","Step 2: Identify y-component = 6","Step 3: 0i contributes nothing","Step 4: Write remaining j component"],"ans":"6j","why":"Zero x-component removes i term"},{"q":"Convert 8i - 5j into coordinate form","hint":"extract components","steps":["Step 1: Identify i coefficient = 8","Step 2: Identify j coefficient = -5","Step 3: Write x = 8","Step 4: Write y = -5","Step 5: Form coordinate pair"],"ans":"(8, -5)","why":"i corresponds to x-axis and j corresponds to y-axis"},{"q":"Add vectors (2i + 3j) + (4i - j)","hint":"combine like terms","steps":["Step 1: Group i terms → 2i + 4i","Step 2: Group j terms → 3j - j","Step 3: Add i components → 6i","Step 4: Add j components → 2j"],"ans":"6i + 2j","why":"Vector addition is done component-wise"},{"q":"Subtract vectors (7i + 2j) - (3i + 5j)","hint":"distribute minus sign","steps":["Step 1: Expand subtraction → 7i + 2j - 3i - 5j","Step 2: Group i terms → 7i - 3i","Step 3: Group j terms → 2j - 5j","Step 4: Simplify components"],"ans":"4i - 3j","why":"Subtraction changes signs of second vector"},{"q":"Find resultant of (5i + 1j) + (-2i + 6j)","hint":"component addition","steps":["Step 1: Add i components → 5 + (-2)","Step 2: Add j components → 1 + 6","Step 3: Simplify each component","Step 4: Write final vector form"],"ans":"3i + 7j","why":"Resultant vector is sum of components"}]'
);

